{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "full",
      "summary_quote": "It defines physical activity to include walking, jumping rope, playing volleyball, other activities that promote fitness and well-being",
      "rationale": "Conveys the listed activities and the fitness-and-well-being qualification for other activities."
    },
    {
      "proposition_id": "P2",
      "status": "full",
      "summary_quote": "structured movement breaks",
      "rationale": "Explicitly includes structured movement breaks in the list of qualifying physical activities."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "time in physical education class when students are physically active",
      "rationale": "Preserves the condition that physical education class time counts only when students are physically active."
    },
    {
      "proposition_id": "P4",
      "status": "full",
      "summary_quote": "It specifies that walking to and from class does not count as physical activity.",
      "rationale": "Expressly conveys the exclusion of walking to and from class."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "Additionally, the bill states that physical activity does not include time when a student is allowed to use an electronic device.",
      "rationale": "Conveys the electronic-device exclusion but omits the amendment target, Section 49-6-1021(b)(2)(A)(ii). That target is material because the supplied replacement fragment does not independently identify what the exclusion modifies."
    },
    {
      "proposition_id": "P6",
      "status": "full",
      "summary_quote": "The proposal also allows a teacher to prevent a student from participating in physical activity to improve that student's behavior.",
      "rationale": "Preserves the teacher's authority, the restriction on student participation, and its behavioral purpose."
    },
    {
      "proposition_id": "P7",
      "status": "full",
      "summary_quote": "These changes would take effect July 1, 2026, for the 2026-2027 school year and beyond.",
      "rationale": "Conveys both the effective date and application to the 2026-2027 school year and subsequent school years."
    }
  ]
}
